// @ts-ignore -- generated by the preceding build step
import * as core from "../../dist"
import type { CadExplosionCollisionCheckWarning } from "circuit-json"
const {
  RootCircuit,
  assembly,
  getAssemblyExplosion,
  checkCircuitJsonAssemblyExplosionCollisions,
} = core
import { loadRp2040ExplosionFixture } from "../../tests/assembly/fixtures/rp2040-explosion/load-fixture"
import { strict as assert } from "node:assert"

const circuit = new RootCircuit()
circuit.add(
  <assembly.device name="SWEEP">
    <assembly.printedpart
      name="SLIDER"
      cadModel={{
        jscad: { type: "cuboid", size: [1, 2, 2] },
        positionOffset: { x: -10, y: 0, z: 0 },
      }}
    />
    <assembly.printedpart
      name="WALL"
      cadModel={{
        jscad: { type: "cuboid", size: [0.01, 8, 8] },
      }}
    />
    <assembly.explosion.stage name="slide">
      <assembly.explosion.move targetRef="SLIDER" offX={20} />
    </assembly.explosion.stage>
  </assembly.device>,
)
await circuit.renderUntilSettled()
assert.equal(getAssemblyExplosion(circuit).collisionCheckStatus, "checked")
const errors = circuit.db.cad_explosion_collision_error.list()
assert.equal(errors.length, 1)
assert.ok(Math.abs(errors[0].swept_intersection_volume_mm3 - 0.04) < 1e-6)
assert.equal(circuit.db.cad_explosion_collision_check_warning.list().length, 0)
console.log("Built-package continuous explosion collision checking passed")

// Exercise the published/bundled import path, including the GLB motor, OBJ bolts
// and generated electronics. This fixture supplies bytes, never collision solids.
const check = await checkCircuitJsonAssemblyExplosionCollisions(
  await loadRp2040ExplosionFixture(),
)
assert.equal(check.status, "incomplete")
assert.equal(
  check.warnings.flatMap(
    (warning: CadExplosionCollisionCheckWarning) => warning.cad_component_ids,
  ).length,
  5,
)
assert.equal(check.errors.length, 4)
console.log("Built-package real imported/generated assembly checking passed")
